import math

def check_integer(n):
    if n < 0:
        return False
    D = 2 * n - 1

    # Handle the case D = 0, though impossible for integer n >= 0
    if D == 0:
        return False

    try:
        fact_n_plus_2 = math.factorial(n + 2)
    except ValueError:
        # Should not happen for non-negative n
        return False

    numerator_term = 3 * (fact_n_plus_2 + 1)

    # Check if the division results in an integer
    return numerator_term % D == 0

# Test n from 0 up to 15
solutions = []
for n in range(16):
    if check_integer(n):
        solutions.append(n)

print("Solutions found up to n=15:", solutions)

import math

def E(n):
    """Calculates E(n) = 3 * ((n+2)! + 1) / (2n - 1)"""
    if n < 0:
        return "Undefined for n < 0"

    # Handle the denominator being zero
    if 2 * n - 1 == 0:
        return "Denominator is zero"

    # Calculate (n+2)!
    try:
        factorial_term = math.factorial(n + 2)
    except OverflowError:
        return "Factorial too large"

    numerator = 3 * (factorial_term + 1)
    denominator = 2 * n - 1

    # Check if the result is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return f"{numerator}/{denominator} (Not integer)"

# Values to check: solutions {0, 1, 2, 4, 12} and neighbors {13, 14, 15}
test_values = [0, 1, 2, 4, 12, 13, 14, 15]
results = {}

for n in test_values:
    result = E(n)
    results[n] = result
    print(f"n={n}: E({n}) = {result}")

print("\n--- Summary ---")
solutions = [n for n, result in results.items() if isinstance(result, int)]
print(f"Verified Integer Solutions: {solutions}")

import math
import itertools

def is_prime(k):
    """Checks if k is a prime number."""
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

def solve_focused_search(limit):
    solutions_found = []
    print(f"Starting focused search up to n={limit}...")

    for n in range(limit + 1):
        D = 2 * n - 1

        # Criteria: D must be composite and gcd(D, 3) == 1
        if D <= 1 or is_prime(D):
            continue

        if math.gcd(D, 3) != 1:
            continue

        # D is composite and not divisible by 3.
        # The condition simplifies to D | (n+2)! + 1

        try:
            # Calculate (n+2)! + 1
            factorial_plus_one = 1
            for i in range(1, n + 3):
                factorial_plus_one *= i
            factorial_plus_one += 1

            # Check divisibility
            if factorial_plus_one % D == 0:
                solutions_found.append(n)
        except OverflowError:
            # Should not happen with Python's arbitrary precision integers 
            # up to n=30, but good practice.
            print(f"Skipping n={n} due to calculation size.")
            continue

    return solutions_found

solutions = solve_focused_search(30)
print("\nSolutions found under focused criteria (n):")
print(solutions)
